107	static int ensure_directory_tree(const char *path)
108	{
109	  char buffer[256];
110	  size_t length;
111	  char *cursor;
112	
113	  if (path == NULL)
114	    {
115	      return -EINVAL;
116	    }
117	
118	  length = strlen(path);
119	  if (length == 0 || length >= sizeof(buffer))
120	    {
121	      return -ENAMETOOLONG;
122	    }
123	
124	  memcpy(buffer, path, length + 1);
125	
126	  for (cursor = buffer + 1; *cursor != '\0'; cursor++)
127	    {
128	      if (*cursor == '/')
129	        {
130	          *cursor = '\0';
131	          if (mkdir(buffer, 0755) < 0 && errno != EEXIST)
132	            {
133	              return -errno;
134	            }
135	          *cursor = '/';
136	        }
137	    }
138	
139	  if (mkdir(buffer, 0755) < 0 && errno != EEXIST)
140	    {
141	      return -errno;
142	    }
143	
144	  return 0;
145	}
