147	static int seed_skill(const struct contest_skill *skill)
148	{
149	  char path[256];
150	  FILE *file;
151	  size_t length;
152	
153	  if (snprintf(path, sizeof(path), "%s/%s.md", CONTEST_SKILLS_DIR,
154	               skill->name) >= (int)sizeof(path))
155	    {
156	      return -ENAMETOOLONG;
157	    }
158	
159	  if (access(path, F_OK) == 0)
160	    {
161	      return 0;
162	    }
163	
164	  file = fopen(path, "w");
165	  if (file == NULL)
166	    {
167	      return -errno;
168	    }
169	
170	  length = strlen(skill->content);
171	  if (fwrite(skill->content, 1, length, file) != length || fclose(file) != 0)
172	    {
173	      return -EIO;
174	    }
175	
176	  printf("[fall_detect_app] seeded skill: %s\n", skill->name);
177	  return 0;
178	}
