206	static int publish_fall_event(const struct qma7981_data_s *sample)
207	{
208	  char content[256];
209	  agent_msg_t message;
210	
211	  if (snprintf(content, sizeof(content),
212	               "fall_suspected: accelerometer impact detected; "
213	               "raw_x=%d raw_y=%d raw_z=%d. Run fall-patrol for camera "
214	               "confirmation and voice-help for a local safety prompt.",
215	               sample->x, sample->y, sample->z) >= (int)sizeof(content))
216	    {
217	      return -ENAMETOOLONG;
218	    }
219	
220	  memset(&message, 0, sizeof(message));
221	  strncpy(message.channel, "system", sizeof(message.channel) - 1);
222	  strncpy(message.chat_id, "fall-detect", sizeof(message.chat_id) - 1);
223	  message.content = strdup(content);
224	  if (message.content == NULL)
225	    {
226	      return -ENOMEM;
227	    }
228	
229	  if (message_bus_push_inbound(&message) < 0)
230	    {
231	      free(message.content);
232	      return -EAGAIN;
233	    }
234	
235	  printf("[fall_detect_app] fall_suspected published: %d,%d,%d\n",
236	         sample->x, sample->y, sample->z);
237	  return 0;
238	}
