250	static int monitor_accelerometer(struct runtime_state *state)
251	{
252	  struct qma7981_data_s sample;
253	  int fd;
254	  int64_t magnitude_sq;
255	  uint32_t debounce_us = 0;
256	  uint32_t sample_count = 0;
257	
258	  fd = open("/dev/accel0", O_RDONLY);
259	  if (fd < 0)
260	    {
261	      printf("[fall_detect_app] /dev/accel0 unavailable: %d; "
262	             "agent remains available in degraded mode\n", errno);
263	      while (!state->agent_finished && !agent_shutdown_requested())
264	        {
265	          usleep(500000);
266	        }
267	      return 0;
268	    }
269	
270	  printf("[fall_detect_app] monitoring /dev/accel0 (threshold=3g)\n");
271	  while (!state->agent_finished && !agent_shutdown_requested())
272	    {
273	      if (read(fd, &sample, sizeof(sample)) != ACCEL_SAMPLE_BYTES)
274	        {
275	          usleep(SENSOR_POLL_DELAY_US);
276	          continue;
277	        }
278	
279	      if ((++sample_count % 50) == 0)
280	        {
281	          printf("[fall_detect_app] sample: x=%d y=%d z=%d\n",
282	                 sample.x, sample.y, sample.z);
283	        }
284	
285	      magnitude_sq = (int64_t)sample.x * sample.x +
286	                     (int64_t)sample.y * sample.y +
287	                     (int64_t)sample.z * sample.z;
288	
289	      if (debounce_us > 0)
290	        {
291	          debounce_us = debounce_us > SENSOR_POLL_DELAY_US
292	                        ? debounce_us - SENSOR_POLL_DELAY_US : 0;
293	        }
294	      else if (magnitude_sq >= ACCEL_THRESHOLD_SQ)
295	        {
296	          publish_fall_event(&sample);
297	          debounce_us = FALL_DEBOUNCE_MS * 1000;
298	        }
299	
300	      usleep(SENSOR_POLL_DELAY_US);
301	    }
302	
303	  close(fd);
304	  return 0;
305	}
