307	int main(int argc, char *argv[])
308	{
309	  struct runtime_state state;
310	  pthread_t agent_thread;
311	  int ret;
312	
313	  (void)argc;
314	  (void)argv;
315	  memset(&state, 0, sizeof(state));
316	
317	  printf("[fall_detect_app] starting Silver Guardian runtime\n");
318	
319	  ret = seed_contest_skills();
320	  if (ret < 0)
321	    {
322	      fprintf(stderr, "[fall_detect_app] skill provisioning failed: %d\n", ret);
323	      return EXIT_FAILURE;
324	    }
325	
326	  ret = message_bus_init();
327	  if (ret < 0)
328	    {
329	      fprintf(stderr, "[fall_detect_app] message bus init failed: %d\n", ret);
330	      return EXIT_FAILURE;
331	    }
332	
333	  ret = pthread_create(&agent_thread, NULL, run_ai_agent, &state);
334	  if (ret != 0)
335	    {
336	      fprintf(stderr, "[fall_detect_app] agent thread creation failed: %d\n", ret);
337	      return EXIT_FAILURE;
338	    }
339	
340	  monitor_accelerometer(&state);
341	  agent_request_shutdown();
342	  pthread_join(agent_thread, NULL);
343	
344	  printf("[fall_detect_app] runtime stopped with result %d\n",
345	         state.agent_result);
346	  return state.agent_result < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
347	}
